changeSet.sql:
CREATE TABLE IF NOT EXISTS spare_part_master ( spare_part_id BIGSERIAL PRIMARY KEY, part_code VARCHAR(80) UNIQUE NOT NULL, part_name VARCHAR(180) NOT NULL, description TEXT, category VARCHAR(100), unit VARCHAR(30) NOT NULL, preferred_vendor_id BIGINT REFERENCES vendor_master(id), status VARCHAR(30) DEFAULT 'ACTIVE', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE IF NOT EXISTS spare_part_site_stock ( stock_id BIGSERIAL PRIMARY KEY, spare_part_id BIGINT NOT NULL REFERENCES spare_part_master(spare_part_id), site_id BIGINT NOT NULL REFERENCES site_master(site_id), current_stock NUMERIC(14,3) DEFAULT 0 NOT NULL, minimum_stock NUMERIC(14,3) DEFAULT 0 NOT NULL, unit_cost NUMERIC(12,2) DEFAULT 0 NOT NULL, storage_location VARCHAR(150), status VARCHAR(30) DEFAULT 'ACTIVE', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uk_spare_part_site_stock UNIQUE (spare_part_id, site_id), CONSTRAINT ck_spare_part_stock_non_negative CHECK (current_stock >= 0), CONSTRAINT ck_spare_part_minimum_non_negative CHECK (minimum_stock >= 0) );
CREATE TABLE IF NOT EXISTS spare_part_transaction ( transaction_id BIGSERIAL PRIMARY KEY, stock_id BIGINT NOT NULL REFERENCES spare_part_site_stock(stock_id), spare_part_id BIGINT NOT NULL REFERENCES spare_part_master(spare_part_id), site_id BIGINT NOT NULL REFERENCES site_master(site_id), transaction_type VARCHAR(40) NOT NULL, quantity NUMERIC(14,3) NOT NULL, unit_cost NUMERIC(12,2) DEFAULT 0 NOT NULL, total_cost NUMERIC(14,2) DEFAULT 0 NOT NULL, stock_before NUMERIC(14,3) NOT NULL, stock_after NUMERIC(14,3) NOT NULL, reference_type VARCHAR(80), reference_id BIGINT, remarks VARCHAR(1000), transaction_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP, created_by BIGINT REFERENCES users(id), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE IF NOT EXISTS maintenance_spare_usage ( usage_id BIGSERIAL PRIMARY KEY, assignment_id BIGINT NOT NULL REFERENCES maintenance_assignment(id), stock_id BIGINT NOT NULL REFERENCES spare_part_site_stock(stock_id), spare_part_id BIGINT NOT NULL REFERENCES spare_part_master(spare_part_id), quantity_used NUMERIC(14,3) NOT NULL, unit_cost NUMERIC(12,2) DEFAULT 0 NOT NULL, total_cost NUMERIC(14,2) DEFAULT 0 NOT NULL, remarks VARCHAR(1000), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uk_assignment_spare_usage UNIQUE (assignment_id, stock_id) );

INSERT INTO permission_master (permission_code, permission_name, module_name, action_name, status, created_at, updated_at) VALUES ('SPARE_PART_VIEW', 'View Spare Parts', 'Spare Parts', 'VIEW', 'ACTIVE', NOW(), NOW()), ('SPARE_PART_CREATE', 'Create Spare Parts', 'Spare Parts', 'CREATE', 'ACTIVE', NOW(), NOW()), ('SPARE_PART_UPDATE', 'Update Spare Parts', 'Spare Parts', 'UPDATE', 'ACTIVE', NOW(), NOW()), ('SPARE_PART_DELETE', 'Delete Spare Parts', 'Spare Parts', 'DELETE', 'ACTIVE', NOW(), NOW()), ('STOCK_TRANSACTION_VIEW', 'View Stock Transactions', 'Stock Transactions', 'VIEW', 'ACTIVE', NOW(), NOW()), ('STOCK_TRANSACTION_CREATE', 'Create Stock Transactions', 'Stock Transactions', 'CREATE', 'ACTIVE', NOW(), NOW()), ('SPARE_USAGE_VIEW', 'View Assignment Spare Usage', 'Spare Usage', 'VIEW', 'ACTIVE', NOW(), NOW()), ('SPARE_USAGE_CREATE', 'Create Assignment Spare Usage', 'Spare Usage', 'CREATE', 'ACTIVE', NOW(), NOW()), ('SPARE_USAGE_UPDATE', 'Update Assignment Spare Usage', 'Spare Usage', 'UPDATE', 'ACTIVE', NOW(), NOW()), ('SPARE_USAGE_DELETE', 'Delete Assignment Spare Usage', 'Spare Usage', 'DELETE', 'ACTIVE', NOW(), NOW()) ON CONFLICT (permission_code) DO NOTHING;
INSERT INTO role_permission (role_id, permission_id) SELECT r.role_id, p.permission_id FROM role_master r JOIN permission_master p ON p.module_name IN ('Spare Parts', 'Stock Transactions', 'Spare Usage') WHERE r.role_code IN ('SUPER_ADMIN', 'ADMIN') ON CONFLICT (role_id, permission_id) DO NOTHING;
INSERT INTO role_permission (role_id, permission_id) SELECT r.role_id, p.permission_id FROM role_master r JOIN permission_master p ON p.permission_code IN ( 'SPARE_PART_VIEW', 'SPARE_PART_CREATE', 'SPARE_PART_UPDATE', 'STOCK_TRANSACTION_VIEW', 'STOCK_TRANSACTION_CREATE', 'SPARE_USAGE_VIEW', 'SPARE_USAGE_CREATE', 'SPARE_USAGE_UPDATE', 'SPARE_USAGE_DELETE' ) WHERE r.role_code IN ('SITE_MANAGER', 'MAINTENANCE_MANAGER') ON CONFLICT (role_id, permission_id) DO NOTHING;
INSERT INTO role_permission (role_id, permission_id) SELECT r.role_id, p.permission_id FROM role_master r JOIN permission_master p ON p.permission_code IN ('SPARE_PART_VIEW', 'STOCK_TRANSACTION_VIEW', 'SPARE_USAGE_VIEW', 'SPARE_USAGE_CREATE') WHERE r.role_code = 'TECHNICIAN' ON CONFLICT (role_id, permission_id) DO NOTHING;
INSERT INTO role_permission (role_id, permission_id) SELECT r.role_id, p.permission_id FROM role_master r JOIN permission_master p ON p.permission_code IN ('SPARE_PART_VIEW', 'STOCK_TRANSACTION_VIEW', 'SPARE_USAGE_VIEW') WHERE r.role_code = 'VIEWER' ON CONFLICT (role_id, permission_id) DO NOTHING;

INSERT INTO permission_master (permission_code, permission_name, module_name, action_name, status, created_at, updated_at) VALUES ('REORDER_VIEW', 'View Reorder Requests', 'Reorder Requests', 'VIEW', 'ACTIVE', NOW(), NOW()), ('REORDER_CREATE', 'Create Reorder Requests', 'Reorder Requests', 'CREATE', 'ACTIVE', NOW(), NOW()), ('REORDER_UPDATE', 'Update Reorder Requests', 'Reorder Requests', 'UPDATE', 'ACTIVE', NOW(), NOW()) ON CONFLICT (permission_code) DO NOTHING;
INSERT INTO role_permission (role_id, permission_id) SELECT r.role_id, p.permission_id FROM role_master r JOIN permission_master p ON p.module_name = 'Reorder Requests' WHERE r.role_code IN ('SUPER_ADMIN', 'ADMIN', 'SITE_MANAGER', 'MAINTENANCE_MANAGER') ON CONFLICT (role_id, permission_id) DO NOTHING;
INSERT INTO role_permission (role_id, permission_id) SELECT r.role_id, p.permission_id FROM role_master r JOIN permission_master p ON p.permission_code = 'REORDER_VIEW' WHERE r.role_code IN ('TECHNICIAN', 'VIEWER') ON CONFLICT (role_id, permission_id) DO NOTHING;
